-- Canonical MySQL 8 schema. Provider-specific DDL is kept separate from SQLite.
CREATE TABLE server_config (id VARCHAR(36) PRIMARY KEY, server_id VARCHAR(36) NOT NULL UNIQUE, server_name VARCHAR(128) NOT NULL, setup_completed BOOLEAN NOT NULL DEFAULT FALSE, database_type VARCHAR(16) NOT NULL, server_version VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, username VARCHAR(32) NOT NULL, username_normalized VARCHAR(32) NOT NULL UNIQUE, display_name VARCHAR(128) NOT NULL, email VARCHAR(254), password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login_at VARCHAR(40), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE roles (id VARCHAR(36) PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL, is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissions (id VARCHAR(36) PRIMARY KEY, name VARCHAR(128) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL, created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id VARCHAR(36) NOT NULL, role_id VARCHAR(36) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id VARCHAR(36) NOT NULL, permission_id VARCHAR(36) NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id)) ENGINE=InnoDB;
CREATE TABLE audit_log (id VARCHAR(36) PRIMARY KEY, actor_user_id VARCHAR(36), action VARCHAR(64) NOT NULL, entity_type VARCHAR(64) NOT NULL, entity_id VARCHAR(36), metadata JSON NOT NULL, ip_address VARCHAR(64), created_at VARCHAR(40) NOT NULL, INDEX idx_audit_created_at(created_at)) ENGINE=InnoDB;
